import zipfile,io,pathlib,json,collections
base=zipfile.ZipFile('BarttoloWorldExpansion-0.12.2-ALTURA-Y-BORDES-test.jar');artifact=zipfile.ZipFile('biome-build.zip');engine=zipfile.ZipFile(io.BytesIO(artifact.read(next(n for n in artifact.namelist() if n.endswith('.jar')))))
updates={n:engine.read(n) for n in engine.namelist() if n.startswith('net/barttolo/bwe/') and n.endswith('.class')};cat=json.load(open('catalogo-biomas-v1.json'));report=json.load(open('biomes-report.json'));verified=json.load(open('biomes-verified.json'))
name='BarttoloWorldExpansion-0.13.0-BETTER-VILLAGE-Y-GRAND-CAPITALS-test.jar'
readme='''BWE 0.13.0 - Better Village y Grand Capitals por bioma\n\nInstalar sustituyendo el BWE anterior en CLIENTE Y SERVIDOR y reiniciar. No borrar config/bwe ni respaldos. Se conservan las 35 opciones anteriores y se agregan 35: 16 variantes de Better Village, 16 capitales de Grand Capitals y 3 estructuras especiales. Total por defecto: 70 opciones en la misma lista /bwe listar.\n\nLas nuevas entradas aparecen agrupadas por bioma, con el bioma escrito en el nombre y en la vista previa. Es una recomendacion de estilo, no una restriccion: se pueden colocar en cualquier bioma. No se agregan listas ni comandos separados.\n\nBIOMAS\nPradera: 9 variantes nuevas. Desierto: 6. Sabana: 6. Nieve: 6. Taiga: 5. Ademas: mansion del bosque oscuro, cabana de bruja del pantano y puesto de saqueadores para varios biomas.\n\nCOLOCACION MANUAL\nNo es necesario instalar Better Village, Library Ferret ni Grand Capitals para usar estos planos en BWE: se incluyen solamente estructuras y metadatos como recursos pasivos, sin codigo ni worldgen de esos mods. BWE no genera estas aldeas automaticamente. Si los mods originales se mantienen instalados por separado, su generacion propia seguira siendo independiente de BWE.\n\nSon planos fijos ensamblados mediante conectores a partir de las piezas originales; no reproducen todas las combinaciones aleatorias ni los procesadores de la generacion natural. Los 16 centros de Better Village y los 16 centros de capitales tienen su propia variante manual. La mansion incluye sus cinco piezas principales. Se recorta el aire exterior de las piezas y se conserva el margen de un bloque.\n\nSe adaptan grass_path a dirt_path y short_grass a grass para 1.20.1. Los pobladores y animales de los marcadores se incluyen segun el diseno, con aspecto de aldeano segun bioma. Se conservan las entidades incluidas en las plantillas, retirando UUID y ajustando posiciones/anclajes al mover o girar la estructura. Las decoraciones de pared se colocan con su anclaje correcto.\n\nLa mansion, el puesto de saqueadores y la cabana de bruja conservan la poblacion hostil del original. La mansion es especialmente exigente: el plano contiene 957 entidades, en su mayoria cuadros, ademas de mobs hostiles. Esta condicion tambien se indica en su vista previa. No es una mansion residencial vacia.\n\nMisma mecanica de limpieza, nivelacion de patios, altura manual, borde continuo, conversion automatica de cofres a Lootr y /bwe deshacer con restauracion persistente de terreno e inventarios. Pirata y Dirigibles mantienen sus excepciones de agua/aire. /bwe escanear -> /bwe listar -> Ver/Elegir -> /bwe altura Y si hace falta -> alejarse -> /bwe crear.\n\nVERIFICACION\nComprobacion fuera del juego de los 35 planos completos: coordenadas, paletas, union de piezas, volumen, limites y presupuesto. Regresion nativa Forge 1.20.1 / Lootr: 2.251 estados de bloques, tipos de entidades y variantes de cuadros validados, lectura del catalogo adicional sin sustituir el anterior, preservacion de paredes ante aire sobrante de otras piezas y cuadro girado colocado con soporte correcto. Pasan tambien las pruebas anteriores de altura, bordes, restauracion, Pirata y Dirigibles. No se ha recorrido visualmente cada aldea dentro del modpack del servidor.\n\nAUTORES\nBetter Village por JTorLeon Studios; Grand Capitals por Lukidon. Archivos originales aportados por el usuario para esta adaptacion privada. No se redistribuye el codigo de esos mods.\n\nCATALOGO NUEVO (medidas totales con margen)\n'''
for e in cat['entries']:readme+=f"- {e['title']}: {e['sizeX']+2} x {e['sizeZ']+2} bloques.\n"
readme+='\nNOTAS DE LA VERSION ANTERIOR\n'+base.read('BWE-LEEME.txt').decode()
with zipfile.ZipFile(name,'w',zipfile.ZIP_DEFLATED) as z:
 for n in base.namelist():
  d=updates.pop(n,base.read(n))
  if n=='META-INF/mods.toml':d=d.replace(b'0.12.2',b'0.13.0')
  if n=='BWE-LEEME.txt':d=readme.encode()
  z.writestr(n,d)
 for n,d in updates.items():z.writestr(n,d)
 for file in ['bwe_better.jar','bwe_capitals.jar','catalogo-biomas-v1.json']:z.write(file,'assets/barttoloworldexpansion/'+file)
 for p in pathlib.Path('biome-previews').glob('*.png'):z.write(p,'assets/barttoloworldexpansion/textures/gui/previews/'+p.name)
 z.writestr('BWE-BIOMAS-PLANOS.json',json.dumps({'source_layouts':report,'verified_layouts':verified},ensure_ascii=False,indent=2))
z=zipfile.ZipFile(name);assert z.testzip() is None
for n in base.namelist():
 if n.startswith('assets/'):assert base.read(n)==z.read(n),n
old=sum(len(json.loads(z.read('assets/barttoloworldexpansion/'+f))['entries']) for f in ['catalogo-iv-v2.json','catalogo-extra-v1.json']);assert old+len(cat['entries'])==70
for archive in ['bwe_better.jar','bwe_capitals.jar']:
 a=zipfile.ZipFile(io.BytesIO(z.read('assets/barttoloworldexpansion/'+archive)));assert all(n.startswith('data/') and '/structures/' in n and n.endswith('.nbt') for n in a.namelist())
assert len(list(pathlib.Path('biome-previews').glob('*.png')))==35
assert 'net/barttolo/bwe/RegressionGameTests.class' not in z.namelist()
print('PASS',name,pathlib.Path(name).stat().st_size,'bytes; 70 entries; original catalogue assets preserved; passive templates only')
